-- Kana: the full gojūon in both scripts, plus dakuten and handakuten.
-- Generated rather than hand-written — a couple of hundred rows of pure table
-- data with no upstream dataset worth a pipeline. This is what makes the review
-- loop real before any of the JMdict/KANJIDIC importers exist.
--
-- Hiragana is ordered before katakana (sort_index 0.. vs 1000..) because that is
-- the order people learn them, and sort_index drives the introduction queue.

-- A typed drill graded as romaji. Its own code, because the generic
-- `reading-input` template grades exact kana — the wrong question for
-- "what sound is か".
   ARRAY['kana'], ARRAY['reading'], 'text', 'fuzzy-romaji', '{}', false, '{"answerScript":"romaji"}', 12, true)
ON CONFLICT (code, language_id) DO NOTHING;

VALUES ('kft-kana-reading-romaji', 'lang-ja', 'kana', 'reading', 'tpl-kana-romaji', 12, false)
ON CONFLICT (language_id, kind, facet, template_id) DO NOTHING;

ON CONFLICT (language_id, script, character) DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT (study_item_id, facet) DO NOTHING;

ON CONFLICT (facet_id, template_id, version) DO NOTHING;
